from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import issue_credit_note
from ledgerly.errors import BillingError
from ledgerly.models import Invoice, LineItem

def inv(status="issued", price="1000.00"):
    return Invoice("inv_1","cus_1",lines=[LineItem("x",1,Decimal(price))],status=status)

# basic
audit.clear()
r = issue_credit_note(inv(), Decimal("10.00"), "goodwill")
print("basic", r, audit.events("credit_note_issued")[-1])

# idempotency: same key returns original, no new audit
r2 = issue_credit_note(inv(), Decimal("10.00"), "goodwill", idempotency_key="k1")
r3 = issue_credit_note(inv(), Decimal("999.00"), "different", idempotency_key="k1")
print("idem", r2, r3, len(audit.events("credit_note_issued")))

# approval
audit.clear()
try:
    issue_credit_note(inv(), Decimal("500.01"), "big")
except BillingError as e: print("approval missing:", e.code)
print("at threshold ok:", issue_credit_note(inv(), Decimal("500.00"), "ok")["amount"])
print("approved ok:", issue_credit_note(inv(), Decimal("600.00"), "ok", approved_by="mgr")["amount"])

# state
try: issue_credit_note(inv("draft"), Decimal("1.00"), "x")
except BillingError as e: print("state:", e.code)
# non-positive
try: issue_credit_note(inv(), Decimal("0.00"), "x")
except BillingError as e: print("zero:", e.code)
# exceeds
try: issue_credit_note(inv(), Decimal("1000.01"), "x")
except BillingError as e: print("exceeds:", e.code)
# missing reason
try: issue_credit_note(inv(), Decimal("1.00"), "")
except BillingError as e: print("reason:", e.code)
# bad type
try: issue_credit_note(inv(), True, "x")
except BillingError as e: print("bool:", e.code)
EOF"}

